-- LibrarAI 예산 원장(A-03) Supabase 스키마
-- References/budget_2026.xlsx(경상남도교육청 K-EduFine 실제 내보내기)를 초기 데이터로 적재한다.
-- Supabase SQL Editor에서 이 파일 전체를 한 번 실행하면 테이블 생성 + 시드 데이터 적재까지 끝난다.
-- 잔액(balance)/잔액예정(planned_balance)은 컬럼으로 저장하지 않고 조회 시 계산한다
-- (balance = budget_amount - executed_amount, planned_balance = balance - planned_amount).

create table if not exists public.budget_lines (
  id uuid primary key default gen_random_uuid(),
  unit_task text not null,        -- 단위과제카드
  budget_kind text,                -- 예산종류 (예산/재배정예산)
  budget_mok text,                 -- 예산목 (210운영비 등)
  item1 text,                      -- 사업항목1
  item2 text,                      -- 사업항목2
  item3 text,                      -- 사업항목3
  item4 text,                      -- 사업항목4
  cost_code text,                  -- 원가통계비목 ([코드]비목명)
  budget_amount bigint not null,   -- 예산액
  executed_amount bigint not null default 0,  -- 결의금액 (누계)
  planned_amount bigint not null default 0,   -- 결의예정금액 (누계)
  unique_key text not null unique, -- 고유값 (조인 키)
  as_of_date date not null default current_date,
  updated_at timestamptz not null default now()
);

create table if not exists public.budget_resolutions (
  id bigserial primary key,
  unique_key text not null references public.budget_lines(unique_key),
  resolved_date date not null,
  resolved_month text,
  description text not null,
  amount bigint not null,
  source text default 'seed',      -- 'seed' | 'a03-web' | 도메인 에이전트 ID
  created_at timestamptz not null default now()
);

create table if not exists public.budget_planned (
  id bigserial primary key,
  unique_key text not null references public.budget_lines(unique_key),
  planned_date date not null,
  planned_month text,
  amount bigint not null,
  description text,
  manager text,
  created_at timestamptz not null default now()
);

alter table public.budget_lines enable row level security;
alter table public.budget_resolutions enable row level security;
alter table public.budget_planned enable row level security;

drop policy if exists "budget_lines public read" on public.budget_lines;
create policy "budget_lines public read" on public.budget_lines for select using (true);

drop policy if exists "budget_resolutions public read" on public.budget_resolutions;
create policy "budget_resolutions public read" on public.budget_resolutions for select using (true);

drop policy if exists "budget_planned public read" on public.budget_planned;
create policy "budget_planned public read" on public.budget_planned for select using (true);

-- INSERT/UPDATE는 의도적으로 정책을 추가하지 않는다 — anon 키로는 쓰기가 불가능하고,
-- service_role 키(서버 전용, api/budget.js)만 RLS를 우회해 기록할 수 있다.



